from __future__ import annotations

import re

__all__ = ["semver_compare"]

_SEMVER_REGEX = re.compile(
    r"""^
    (?P<major>0|[1-9]\d*)
    \.
    (?P<minor>0|[1-9]\d*)
    \.
    (?P<patch>0|[1-9]\d*)
    (?:-(?P<prerelease>[0-9A-Za-z.-]+))?
    (?:\+(?P<build>[0-9A-Za-z.-]+))?
    $""",
    re.VERBOSE,
)


class InvalidVersionError(ValueError):
    """Raised when a version string does not conform to Semantic Versioning."""


def _parse_version(version_str: str) -> tuple[int, int, int, list[str | int] | None]:
    if not isinstance(version_str, str):
        raise InvalidVersionError("Version must be a string")

    match = _SEMVER_REGEX.match(version_str)
    if not match:
        raise InvalidVersionError(f"Invalid semantic version: '{version_str}'")

    major = int(match.group("major"))
    minor = int(match.group("minor"))
    patch = int(match.group("patch"))
    prerelease_str = match.group("prerelease")

    prerelease: list[str | int] | None = None
    if prerelease_str is not None:
        prerelease = []
        parts = prerelease_str.split(".")
        for part in parts:
            if not part:
                raise InvalidVersionError(f"Invalid empty identifier in pre-release: '{prerelease_str}'")
            if part.isdigit():
                if len(part) > 1 and part[0] == "0":
                    raise InvalidVersionError(f"Numeric pre-release identifier cannot have leading zeros: '{part}'")
                prerelease.append(int(part))
            else:
                prerelease.append(part)

    return major, minor, patch, prerelease


def _compare_prerelease(a: list[str | int] | None, b: list[str | int] | None) -> int:
    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1

    for id_a, id_b in zip(a, b):
        is_a_int = isinstance(id_a, int)
        is_b_int = isinstance(id_b, int)

        if is_a_int and is_b_int:
            if id_a < id_b:
                return -1
            if id_a > id_b:
                return 1
        elif not is_a_int and not is_b_int:
            if id_a < id_b:
                return -1
            if id_a > id_b:
                return 1
        else:
            # Numeric identifiers always have lower precedence than non-numeric identifiers
            return -1 if is_a_int else 1

    if len(a) < len(b):
        return -1
    if len(a) > len(b):
        return 1

    return 0


def semver_compare(a: str, b: str) -> int:
    """Compare two semantic version strings according to semver.org rules.

    Returns:
        -1 if a < b
         0 if a == b
         1 if a > b
    """
    major_a, minor_a, patch_a, pre_a = _parse_version(a)
    major_b, minor_b, patch_b, pre_b = _parse_version(b)

    if major_a != major_b:
        return -1 if major_a < major_b else 1

    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1

    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    return _compare_prerelease(pre_a, pre_b)
